std::unique_ptr<Workspace> mount(const fs::path& root){
 fs::path cache;if(ps_lab_active())cache=fs::u8path(ps_lab_preferences()).parent_path()/"database-drafts";
 else {const char* local=std::getenv("LOCALAPPDATA");if(!local)throw std::runtime_error("No local recovery folder");uint64_t hash=14695981039346656037ULL;for(unsigned char c:root.u8string()){hash^=c;hash*=1099511628211ULL;}cache=fs::u8path(local)/"PowerSurge/authoring"/std::to_string(hash);}
 return std::make_unique<Workspace>(root,cache);
}
std::string section_for(const std::string& type){return (type=="sky_profile"||type=="sky")?"Skies":(type=="terrain_material_library"||type=="material-library")?"Terrain":type=="light"?"Lights":(type=="lighting_profile"||type=="lighting")?"Lighting":(type=="shader_profile"||type=="shader")?"Shader Profiles":type=="level"?"Levels":type=="sequence"?"Sequences":type=="field"?"Fields":type=="dialogue"?"Dialogue & Choices":type=="effect"?"Effects":type=="switch"?"Switches":type=="variable"?"Variables":type=="event"?"Common Events":type=="item"?"Items":"";}
