std::string request_text(const char* value,size_t limit,bool required=false){if(!value){if(required)throw std::runtime_error("Required request field missing");return {};}
 size_t n=0;for(;n<=limit&&value[n];++n)if(static_cast<unsigned char>(value[n])<32)throw std::runtime_error("Control character in editor request");if(n>limit||(required&&!n))throw std::runtime_error("Invalid editor request field length");return std::string(value,n);}

bool editing_current(){auto* game=asset_gamedir();return workspace&&game&&fs::canonical(fs::u8path(game))==workspace->root();}
void retain(){if(ps_lab_active()&&workspace&&workspace->dirty()&&!ps_lab_retain_project(workspace->root().u8string().c_str(),"Database work and draft recovery retained"))throw std::runtime_error("Cannot retain this authoring project; draft preserved. Reopen its owned source session before saving.");}
void save(Document& d){retain();workspace->save(d);if(d.error.empty())message="Saved "+d.id+". Start a new test to use saved definitions.";retain();if(editing_current())ps_lab_mark_saved();}
