void render_smoke_tick(){
 if(render_smoke_stage<0||render_smoke_stage>=4||!workspace)return;
 bool previous_view=source_view;source_view=false;
 std::shared_ptr<Document> document;std::string original;
 try{
  const char* ids[]={"material-library:terrain","material-library:terrain","light:torch","shader:terrain-lit"};
  document=workspace->open(ids[render_smoke_stage]);original=document->source;auto j=parse(original);
  if(render_smoke_stage==0)j["materials"][0]["tint"]=Json::array();
  else if(render_smoke_stage==1)j["materials"][0]["name"]=7;
  else if(render_smoke_stage==2)j.erase("range_m");
  else j["parameters"]["roughness"]["default"]="broken";
  workspace->edit(*document,j.dump());
  ImGui::BeginChild("Rendering source recovery check",ImVec2(1,1));
  int ids_before=ImGui::GetCurrentWindow()->IDStack.Size,disabled_before=ImGui::GetCurrentContext()->DisabledStackSize;
  document_view(document);
  bool balanced=ids_before==ImGui::GetCurrentWindow()->IDStack.Size&&disabled_before==ImGui::GetCurrentContext()->DisabledStackSize;
  bool raii=true;try{RenderFormId id("native-raii-check");RenderFormDisabled disabled(true);throw std::runtime_error("intentional scoped unwind");}catch(const std::exception&){}
  raii=ids_before==ImGui::GetCurrentWindow()->IDStack.Size&&disabled_before==ImGui::GetCurrentContext()->DisabledStackSize;
  ImGui::EndChild();workspace->edit(*document,original);source_view=previous_view;
  if(!balanced||!raii)throw std::runtime_error("Rendering form failed to restore ImGui stacks");render_smoke_checks+=2;render_smoke_stage++;
 }catch(const std::exception& e){if(document&&!original.empty())workspace->edit(*document,original);source_view=previous_view;render_smoke_stage=-2;message=e.what();}
}
