 if(!ps_lab_automatic()||!visible||section!="Skies")return 0;
 if(source_view){source_view=false;return 0;}
 if(ImGui::GetCurrentContext()->ErrorCountCurrentFrame)return -1;
 return sky_form_drawn?1:0;
